const $=s=>document.querySelector(s),app=$('#app');
const api=async(path,data)=>{const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Request failed');return j};
// Persist the guest pass on the device so refreshing and launching the installed app do not lose the stay.
const q=new URLSearchParams(location.search);
const isStandalone=window.matchMedia?.('(display-mode: standalone)').matches || window.navigator.standalone===true;
const queryToken=q.get('guest');
let storedToken='';
try {storedToken=localStorage.getItem('stayos-guest-pass')||''} catch (_) {}
const token=queryToken || ((isStandalone || location.pathname==='/guest') ? storedToken : '');
if(queryToken){try{localStorage.setItem('stayos-guest-pass',queryToken)}catch(_){}}
// Installed shortcut must include its own guest pass, rather than opening the admin home page.
if(token){const manifest=document.querySelector('link[rel="manifest"]');if(manifest)manifest.href='/api/guest-manifest?token='+encodeURIComponent(token)}

const themePresets={luxury:{primary:'#173e35',accent:'#d6bc83'},ocean:{primary:'#155a73',accent:'#e4bf80'},boutique:{primary:'#303039',accent:'#b3a593'}};
