// Guest pages are real browser history entries. Back returns to the previous guest page.
const guestPages=new Set(['home','service','menu','activities','mine','stay','chat','explore']);
function navigateGuest(next){
 if(!token || !guest || !guestPages.has(next))return;
 if(next===page)return;
 page=next;
 try{history.pushState({stayosGuestPage:next},'',location.pathname+location.search+location.hash);sessionStorage.setItem('stayos-current-page-'+token.slice(0,16),next)}catch(_){}
 if(next==='chat'){chatUnread=false;chatGuestReadId=chatGuestLatest;storeReadId('guest',chatGuestReadId)}
 render();window.scrollTo(0,0);
}
window.addEventListener('popstate',e=>{
 if(!token||!guest)return;
 const next=e.state?.stayosGuestPage;
 page=guestPages.has(next)?next:'home';
 if(page==='chat'){chatUnread=false;chatGuestReadId=chatGuestLatest;storeReadId('guest',chatGuestReadId)}
 render();window.scrollTo(0,0);
});
function storeReadId(kind,id){try{localStorage.setItem('stayos-'+kind+'-chat-read-'+(kind==='guest'?token.slice(0,16):'staff'),String(id))}catch(_){}}
function getReadId(kind){try{return Number(localStorage.getItem('stayos-'+kind+'-chat-read-'+(kind==='guest'?token.slice(0,16):'staff'))||0)}catch(_){return 0}}
function getThreadRead(id){try{return Number(localStorage.getItem('stayos-staff-thread-read-'+id)||0)}catch(_){return 0}}
function markThreadRead(id,last){try{localStorage.setItem('stayos-staff-thread-read-'+id,String(last||0))}catch(_){}}
function countUnreadThreads(threads){return threads.filter(x=>(x.latest_guest_id||0)>getThreadRead(x.stay_id)).length}
let chatGuestReadId=0,staffChatReadId=0,chatUnreadCount=0,staffUnreadCount=0,guestSoundEnabled=false,guestAudioContext=null;
const originalTitle=document.title;
function updateNotificationTitle(){document.title=(chatUnreadCount+staffUnreadCount>0?'● ':'')+originalTitle}
function guestSoundOn(){
 try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error('Audio unavailable');guestAudioContext=guestAudioContext||new AC();guestAudioContext.resume();guestSoundEnabled=true;render()}catch(e){setMessage(e.message)}
}
function beepGuest(){if(!guestSoundEnabled||!guestAudioContext)return;try{const n=guestAudioContext.currentTime;for(const [i,f] of [[0,700],[1,950]]){const o=guestAudioContext.createOscillator(),g=guestAudioContext.createGain();o.frequency.value=f;g.gain.setValueAtTime(.0001,n+i*.19);g.gain.exponentialRampToValueAtTime(.12,n+i*.19+.02);g.gain.exponentialRampToValueAtTime(.0001,n+i*.19+.16);o.connect(g);g.connect(guestAudioContext.destination);o.start(n+i*.19);o.stop(n+i*.19+.17)}}catch(_){}}

