async function loadMine(){return api('my?token='+encodeURIComponent(token))}
function step(id,max,value){return `<div class="stepper"><button onclick="requestStep('${id}',-1,${max})">−</button><b>${value}</b><button onclick="requestStep('${id}',1,${max})">+</button></div>`}
function requestStep(id,d,max){requestsQty[id]=Math.max(0,Math.min(max,(requestsQty[id]||0)+d));render()}
let amenityItems=products.map(([id,icon,basis,period])=>({id,name:id,name_he:(dict.he[id]||id),basis,period,image:id+'.svg',enabled:1}));
let myData={requests:[],bookings:[],folio:[]};let allActivities=[];let guestChat=[],adminThreads=[],adminChat=[],chatStayId=null,chatGuestLatest=0,chatStaffLatest=0,chatUnread=false,staffChatUnread=false,chatPollBusy=false,chatInitialized=false;
function services(){let now=new Date();return `<div class="pad"><h2>🛎️ ${t('service')}</h2><p class="sub">${t('room')} ${esc(guest.room)} · ${guest.guests} ${t('guests')}</p>${amenityItems.map(({id,name,name_he,basis,period,image})=>{let used=myData.requests.filter(x=>x.item===id&&(period==='stay'||new Date(x.created).toDateString()===now.toDateString())).reduce((n,x)=>n+x.qty,0);let max=Math.max(0,(basis==='guest'?guest.guests:2)-used);return `<div class="product"><img src="/assets/${esc(image)}" alt="${esc(language==='he'?name_he:name)}"><div class="detail"><strong>${esc(language==='he'?name_he:name)}</strong><div class="sub">${t('limit')}: ${max}</div></div>${step(id,max,Math.min(requestsQty[id]||0,max))}</div>`}).join('')}<div class="product"><img src="/assets/cleaning.svg" alt="Housekeeping"><div class="detail"><strong>${t('clean')}</strong><div class="sub">${tr('צוות משק הבית','Housekeeping team')}</div></div><button class="btn secondary tiny" onclick="sendCleaning()">+ ${t('send')}</button></div><button class="btn" style="width:100%" onclick="sendItems()">${t('send')} →</button></div>`}
async function sendCleaning(){try{await api('requests',{token,item:'cleaning',qty:1});await refreshGuest();setMessage(tt('housekeepingReceived'))}catch(e){setMessage(e.message)}}
async function sendItems(){const entries=amenityItems.filter(x=>(requestsQty[x.id]||0)>0).map(x=>[x.id]);if(!entries.length)return setMessage(tt('chooseFirst'));try{for(const x of entries)await api('requests',{token,item:x[0],qty:requestsQty[x[0]]});requestsQty={};await refreshGuest();setMessage(tt('requestReceived'))}catch(e){await refreshGuest();setMessage(e.message)}}
let menuItems=[],menuOrders=[],menuCart={},deliveryArea='room',deliveryDetail='',deliveryNote='',foodSubmitting=false,foodRequestKey=null;
const deliverAreas=['room','pool','lobby','beach','restaurant','garden'];
const getItemName=p=>language==='he'?p.name_he:p.name;
function menuView(){const categories=[['drinks',tt('categoryDrinks')],['food',tt('categoryFood')],['snacks',tt('categorySnacks')]];const total=menuItems.reduce((a,p)=>a+p.price_cents*(menuCart[p.id]||0),0);return `<div class="pad menu-page"><div class="section-kicker">AZURA · ${tt('menu')}</div><h2>🍹 ${tt('menu')}</h2><p class="sub">${tt('menuIntro')}</p><div class="menu-categories">${categories.map(([cat,title])=>`<section><h3>${title}</h3><div class="menu-grid">${menuItems.filter(p=>p.category===cat).map(p=>`<div class="menu-card"><img src="/assets/${esc(p.image)}" alt="${esc(getItemName(p))}"><div class="menu-card-info"><strong>${esc(getItemName(p))}</strong><p class="sub">${esc(language==='he'?p.description_he:p.description)}</p><div class="row"><b>${money(p.price_cents)}</b><div class="stepper"><button onclick="menuStep(${p.id},-1)">−</button><b>${menuCart[p.id]||0}</b><button onclick="menuStep(${p.id},1)">+</button></div></div></div></div>`).join('')}</div></section>`).join('')}</div><div class="card pad delivery-panel"><h3>📍 ${tt('delivery')}</h3><div class="delivery-areas">${deliverAreas.map(area=>`<button class="delivery-chip ${deliveryArea===area?'chosen':''}" onclick="changeDelivery('${area}')">${{room:'🚪',pool:'🏊',lobby:'🛎️',beach:'🏖️',restaurant:'🍽️',garden:'🌴'}[area]} ${area==='room'?tt('roomDelivery'):tt(area)}</button>`).join('')}</div>${deliveryArea==='room'?`<p class="sub">${t('room')} ${esc(guest.room)}</p>`:`<label>${tt('locationDetails')}</label><input id="delivery-detail" value="${esc(deliveryDetail)}" maxlength="80" placeholder="${tt('locationHint')}" oninput="deliveryDetail=this.value;foodRequestKey=null">`}<label>${tt('deliveryNote')}</label><textarea id="delivery-note" rows="2" maxlength="250" placeholder="${tt('noteHint')}" oninput="deliveryNote=this.value;foodRequestKey=null">${esc(deliveryNote)}</textarea><div class="folio-total"><span>${tt('total')}</span><strong>${money(total)}</strong></div><p class="sub">${tt('billDisclaimer')}</p><button class="btn" style="width:100%" ${!total?'disabled':''} onclick="placeFoodOrder()">${tt('orderNow')} · ${money(total)}</button></div></div>`}
function menuStep(id,d){foodRequestKey=null;menuCart[id]=Math.max(0,Math.min(12,(menuCart[id]||0)+d));render()}
function changeDelivery(a){foodRequestKey=null;deliveryArea=a;deliveryDetail='';render()}
async function placeFoodOrder(){if(foodSubmitting)return;const items=Object.entries(menuCart).filter(([,qty])=>qty>0).map(([id,qty])=>({product_id:Number(id),qty}));if(!items.length)return setMessage(tt('chooseFirst'));if(deliveryArea!=='room'&&deliveryDetail.trim().length<2)return setMessage(tt('locationDetails')+' — '+tt('locationHint'));foodSubmitting=true;foodRequestKey=foodRequestKey||('order-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));try{const result=await api('orders',{token,request_key:foodRequestKey,items,delivery_area:deliveryArea,delivery_detail:deliveryArea==='room'?guest.room:deliveryDetail.trim(),note:deliveryNote.trim()});menuCart={};foodRequestKey=null;deliveryDetail='';deliveryNote='';await refreshGuest();menuOrders=await api('orders/guest?token='+encodeURIComponent(token));setMessage(tt('orderSuccess')+' #'+result.id+' · '+money(result.total_cents))}catch(e){setMessage(e.message)}finally{foodSubmitting=false}}
function activityCards(){if(!guest.zones.includes('activities'))return `<div class="pad"><h3>${tt('notAvailable')}</h3></div>`;let upcoming=allActivities.filter(a=>new Date(a.starts).getTime()>Date.now());let days=[...new Set(upcoming.map(a=>new Date(a.starts).toDateString()))];let chosen=window.dayChoice||days[0];if(!days.includes(chosen))chosen=days[0];return `<div class="pad"><h2>🌴 ${t('activities')}</h2><div class="tabbar">${days.map(d=>`<button class="${d===chosen?'active':''}" onclick="window.dayChoice='${esc(d)}';render()">${new Date(d).toLocaleDateString(language==='he'?'he-IL':'en-GB',{weekday:'short',day:'numeric',month:'short'})}</button>`).join('')}</div><div class="stack">${upcoming.filter(a=>new Date(a.starts).toDateString()===chosen).map(a=>{const booked=myData.bookings.find(b=>b.activity_id===a.id);const left=a.capacity-a.booked;return `<div class="card"><img class="activity-img" src="${imageFor(a.image)}" alt="${esc(localized(a.title,activityHe))}"><div class="activity-info"><div class="row"><span class="pill">${time(a.starts)} · ${esc(localized(a.location,locHe))}</span><span class="pill green">${a.price?money(a.price*100)+' / '+tt('person'):t('free')}</span></div><h3>${esc(localized(a.title,activityHe))}</h3><p class="sub">${esc(localized(a.description,activityDescHe))}</p><div class="row"><span class="sub">${left} ${t('available')}</span>${booked?`<button class="btn tiny secondary" onclick="cancelBooking(${a.id})">✓ ${booked.qty} · ${t('cancel')}</button>`:`<button class="btn tiny" ${left===0?'disabled':''} onclick="bookActivity(${a.id})">${t('book')} →</button>`}</div></div></div>`}).join('')}</div></div>`}
function bookActivity(id){
 const a=allActivities.find(x=>x.id===id);if(!a)return;
 const max=Math.min(guest.guests,a.capacity-a.booked);if(max<1)return setMessage(tt('notAvailable'));
 const overlay=document.createElement('div');overlay.className='booking-overlay';
 overlay.innerHTML=`<div class="booking-modal" role="dialog" aria-modal="true"><button class="booking-close" aria-label="Close">×</button><div class="section-kicker">${tt('activities')}</div><h2>${esc(localized(a.title,activityHe))}</h2><p class="sub">${esc(localized(a.description,activityDescHe))}</p><p class="booking-date">${localeDate(a.starts)} · ${esc(localized(a.location,locHe))}</p><label>${tt('participants')} · ${tt('upTo')} ${max}</label><select id="booking-persons">${Array.from({length:max},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}</select><div class="booking-total">${tt('total')} <strong id="booking-total-text">${a.price?money(a.price*100):tt('free')}</strong></div><button class="btn booking-confirm">${t('confirm')}</button><p class="sub">${tt('billDisclaimer')}</p></div>`;
 document.body.appendChild(overlay);const selector=overlay.querySelector('#booking-persons');selector.onchange=()=>{overlay.querySelector('#booking-total-text').textContent=a.price?money(a.price*100*Number(selector.value)):tt('free')};
 const close=()=>overlay.remove();overlay.addEventListener('click',e=>{if(e.target===overlay)close()});overlay.querySelector('.booking-close').onclick=close;
 overlay.querySelector('.booking-confirm').onclick=async()=>{const button=overlay.querySelector('.booking-confirm');button.disabled=true;try{await api('bookings',{token,activity_id:id,qty:Number(selector.value)});close();await refreshGuest();setMessage(tt('activityConfirmed'))}catch(e){button.disabled=false;close();setMessage(e.message)}};
}

async function cancelBooking(id){try{await api('cancel-booking',{token,activity_id:id});await refreshGuest();setMessage(tt('activityCanceled'))}catch(e){setMessage(e.message)}}
function mine(){const folio=myData.folio||[];const outstanding=folio.filter(f=>f.status==='open').reduce((s,f)=>s+f.amount_cents,0);return `<div class="pad"><h2>☷ ${t('mine')}</h2><div class="card pad bill-summary"><span>${tt('bill')} · ${tt('pending')}</span><h2>${money(outstanding)}</h2><p class="sub">${tt('billDisclaimer')}</p></div><h3>${tt('orders')}</h3>${menuOrders.length?menuOrders.map(o=>`<div class="product"><div class="detail"><strong>#${o.id} · ${o.delivery_area==='room'?tt('roomDelivery'):tt(o.delivery_area)} ${esc(o.delivery_detail)}</strong><div class="sub">${o.lines.map(z=>esc(orderedProductName(z.product_name))+' × '+z.qty).join(' · ')}</div><small>${localeDate(o.created)}</small></div><div><strong>${money(o.total_cents)}</strong><div class="pill">${tt('status'+({new:'New',preparing:'Preparing',on_way:'OnWay',delivered:'Delivered',cancelled:'Cancelled'}[o.status]||'New'))}</div></div></div>`).join(''):`<p class="sub">${tt('noOrders')}</p>`}<h3>${tt('requests')}</h3>${myData.requests.length?myData.requests.map(r=>`<div class="product"><div class="detail"><strong>${esc(r.item==='cleaning'?t('clean'):(amenityItems.find(x=>x.id===r.item)?.[language==='he'?'name_he':'name']||t(r.item)||r.item))} × ${r.qty}</strong><div class="sub">${localeDate(r.created)}</div></div><span class="status ${r.status}">${esc(r.status==='new'?tt('statusNew'):r.status==='done'?tr('הושלם','Completed'):tr('בטיפול','In progress'))}</span></div>`).join(''):`<p class="sub">${t('noRequests')}</p>`}<h3>${tt('bookings')}</h3>${myData.bookings.length?myData.bookings.map(b=>`<div class="product"><div class="detail"><strong>${esc(localized(b.title,activityHe))}</strong><div class="sub">${localeDate(b.starts)} · ${b.qty} ${tt('guests')}</div></div><button class="btn tiny secondary" onclick="cancelBooking(${b.activity_id})">${t('cancel')}</button></div>`).join(''):`<p class="sub">${tt('emptyBookings')}</p>`}<h3>${tt('bill')}</h3>${folio.length?folio.map(f=>`<div class="product"><div class="detail"><strong>${esc(folioDescription(f))}</strong><div class="sub">${localeDate(f.created)}</div></div><div><strong>${money(f.amount_cents)}</strong><div class="pill">${tt(f.status==='open'?'pending':f.status==='settled'?'settled':'void')}</div></div></div>`).join(''):`<p class="sub">${tt('noCharges')}</p>`}</div>`}
function stayView(){const rt=roomTypeById(guest.room_type_id);return `<div class="pad"><h2>✧ ${tt('roomDetails')}</h2>${rt?`<div class="card"><img class="room-photo" src="${roomImage(rt.image)}" alt=""><div class="pad"><h3>${esc(localized(rt.name,roomHe))}</h3><p class="sub">${esc(localized(rt.description,roomDescHe))}</p><span class="pill">${esc(rt.size)} · ${tt('upTo')} ${rt.max_guests} ${tt('guests')}</span></div></div>`:''}<div class="card pad" style="margin-top:14px"><p><strong>${t('room')}:</strong> ${esc(guest.room)}</p><p><strong>${t('guests')}:</strong> ${guest.guests}</p><p><strong>${tt('checkin')}:</strong> ${localeDate(guest.start)}</p><p><strong>${tt('checkout')}:</strong> ${localeDate(guest.ends)}</p></div></div>`}
function exploreView(){const entries=[[tt('about'),tr('נופש טרופי מוקפד שנוצר לרגעים בלתי נשכחים.','A tropical escape for unforgettable moments.'),'resort-hero.webp'],[tt('dining'),tr('טעמים מקומיים במסעדה מול הים.','Seasonal cuisine in an elegant oceanfront setting.'),'dining.webp'],[tt('spa'),tr('טיפולים מפנקים לחידוש האנרגיה.','Restore body and mind with wellness rituals.'),'wellness-spa.webp'],[tt('beachPool'),tr('בריכת אינפיניטי וחוף טרופי.','Relax beside the infinity pool.'),'resort-pool.webp']];return `<div class="pad premium-content"><div class="section-kicker">AZURA RESORT</div><h2>${tt('resortGuide')}</h2><p class="sub">${tt('aboutDescription')}</p><div class="editorial-list">${entries.map(([title,desc,image])=>`<article class="editorial-card"><img src="/assets/${image}" alt=""><div><h3>${title}</h3><p>${desc}</p></div></article>`).join('')}</div><div class="card pad"><h3>${tt('resortGuide')}</h3><p>${tt('checkin')}: 14:00 · ${tt('checkout')}: 11:00</p><button class="btn" onclick="navigateGuest('chat')">${tt('contact')}</button></div><p class="sub">${tr('מלון AZURA הוא מלון דוגמה בדיוני. התמונות להמחשה בלבד.','AZURA is a fictional demo resort. Photos are illustrative.')}</p></div>`}

function chatTime(value){return new Date(value).toLocaleTimeString(language==='he'?'he-IL':'en-GB',{hour:'2-digit',minute:'2-digit'})}
function chatBubbles(list,role){return list.length?list.map(m=>`<div class="chat-line ${m.sender===role?'out':'in'}"><div class="chat-bubble"><div>${esc(m.body)}</div><time>${chatTime(m.created)} · ${m.sender==='reception'?tr('קבלה','Reception'):tr('אורח','Guest')}</time></div></div>`).join(''):`<div class="chat-empty">${tt('chatEmpty')}</div>`}
function chatView(){return `<div class="chat-page"><div class="chat-heading"><span class="chat-avatar">✦</span><div><h2>${t('chat')}</h2><p class="sub">${esc(hotelSettings.hotel_name)} · ${t('room')} ${esc(guest.room)} · ${tt('chatHint')}</p></div><button class="btn tiny secondary" onclick="guestSoundOn()">${guestSoundEnabled?'🔔 '+tt('soundOn'):'🔕 '+tt('enableSound')}</button></div><div class="chat-messages" id="guest-chat-messages">${chatBubbles(guestChat,'guest')}</div><form class="chat-compose" onsubmit="sendGuestChat(event)"><input id="guest-chat-input" maxlength="1500" autocomplete="off" aria-label="${tt('sendMessage')}" placeholder="${tt('chatPlaceholder')}" required><button class="btn" type="submit" aria-label="Send message">➤</button></form><p class="chat-disclaimer">${tt('emergency')}</p></div>`}
async function sendGuestChat(e){e.preventDefault();const el=$('#guest-chat-input');const body=el?.value.trim();if(!body)return;el.disabled=true;try{await api('chat/guest',{token,message:body});guestChat=(await api('chat/guest?token='+encodeURIComponent(token))).messages;chatGuestLatest=Math.max(chatGuestLatest,...guestChat.filter(x=>x.sender==='reception').map(x=>x.id),0);chatUnread=false;render();scrollChat('guest-chat-messages')}catch(err){el.disabled=false;setMessage(err.message)}}
function scrollChat(id){requestAnimationFrame(()=>{const el=document.getElementById(id);if(el)el.scrollTop=el.scrollHeight})}
function adminChatView(){return `<div class="chat-layout"><section class="chat-sidebar"><div class="chat-side-title"><h2>Guest Conversations</h2><p class="sub">Live inbox · AZURA RESORT</p></div><input id="chat-room-search" placeholder="Search room…" oninput="filterChatRooms()"><div id="chat-threads">${adminThreads.map(th=>`<button class="thread ${chatStayId===th.stay_id?'selected':''}" data-thread-room="${esc(th.room)}" onclick="openAdminChat(${th.stay_id})"><span class="thread-room">Room ${esc(th.room)} ${(th.latest_guest_id||0)>getThreadRead(th.stay_id)?`<span class="unread-badge">NEW</span>`:''}</span><span class="thread-preview">${esc(th.latest||'New conversation')}</span><small>${esc(th.last_at?localeDate(th.last_at):'')}</small></button>`).join('')||'<p class="sub" style="padding:18px">No conversations yet.</p>'}</div></section><section class="chat-admin-panel"><div class="chat-heading"><span class="chat-avatar">✦</span><div><h2>${chatStayId?'Room '+esc(adminThreads.find(x=>x.stay_id===chatStayId)?.room||chatStayId):'Select a conversation'}</h2><p class="sub">Private conversation for this guest stay</p></div></div><div class="chat-messages" id="admin-chat-messages">${chatStayId?chatBubbles(adminChat,'reception'):'<div class="chat-empty">Choose a room on the left to start replying.</div>'}</div>${chatStayId?`<form class="chat-compose" onsubmit="sendAdminChat(event)"><input id="admin-chat-input" maxlength="1500" autocomplete="off" placeholder="Write a reply to this room…" aria-label="Reply" required><button type="submit" class="btn">Send ➤</button></form>`:''}</section></div>`}
function filterChatRooms(){const q=($('#chat-room-search')?.value||'').toLowerCase();document.querySelectorAll('[data-thread-room]').forEach(x=>x.style.display=x.dataset.threadRoom.toLowerCase().includes(q)?'':'none')}
async function openAdminChat(id){chatStayId=id;adminChat=(await api('chat/admin?stay_id='+id)).messages;chatStaffLatest=Math.max(chatStaffLatest,...adminChat.filter(x=>x.sender==='guest').map(x=>x.id),0);markThreadRead(id,Math.max(0,...adminChat.filter(x=>x.sender==='guest').map(x=>x.id)));staffUnreadCount=countUnreadThreads(adminThreads);staffChatUnread=staffUnreadCount>0;updateNotificationTitle();render();scrollChat('admin-chat-messages')}
async function sendAdminChat(e){e.preventDefault();const el=$('#admin-chat-input');const body=el?.value.trim();if(!body||!chatStayId)return;el.disabled=true;try{await api('chat/admin',{stay_id:chatStayId,message:body});adminChat=(await api('chat/admin?stay_id='+chatStayId)).messages;adminThreads=await api('chat/threads');render();scrollChat('admin-chat-messages')}catch(err){el.disabled=false;setMessage(err.message)}}
async function pollChats(){
 if(!token&&!adminSigned)return;
 if(document.hidden||chatPollBusy)return;chatPollBusy=true;
 try{
  if(token&&guest){
   const next=(await api('chat/guest?token='+encodeURIComponent(token))).messages;
   const latest=Math.max(0,...next.filter(x=>x.sender==='reception').map(x=>x.id));
   if(latest>chatGuestLatest){beepGuest()}
   chatGuestLatest=latest;
   if(page==='chat'){chatGuestReadId=latest;storeReadId('guest',latest)}
   chatUnreadCount=next.filter(x=>x.sender==='reception'&&x.id>chatGuestReadId).length;
   chatUnread=chatUnreadCount>0;
   updateNotificationTitle();
   if(JSON.stringify(guestChat)!==JSON.stringify(next)){
    guestChat=next;
    if(page==='chat'&&document.activeElement?.matches('#guest-chat-input')){
     const area=$('#guest-chat-messages');if(area){area.innerHTML=chatBubbles(guestChat,'guest');area.scrollTop=area.scrollHeight}
    }else{render();if(page==='chat')scrollChat('guest-chat-messages')}
   }
  }else if(!token){
   const threads=await api('chat/threads');
   const latestId=Math.max(0,...threads.map(x=>x.latest_guest_id||0));
   if(chatInitialized&&latestId>chatStaffLatest){playAlert()}
   chatInitialized=true;chatStaffLatest=latestId;
   if(chatStayId&&adminTab==='chat'){
    const next=(await api('chat/admin?stay_id='+chatStayId)).messages;
    const unread=next.filter(x=>x.sender==='guest'&&x.id>staffChatReadId);
    if(unread.length){markThreadRead(chatStayId,Math.max(0,...next.filter(x=>x.sender==='guest').map(x=>x.id)))}
    if(JSON.stringify(next)!==JSON.stringify(adminChat)){
     adminChat=next;
     if(document.activeElement?.matches('#admin-chat-input')){
      const area=$('#admin-chat-messages');if(area){area.innerHTML=chatBubbles(adminChat,'reception');area.scrollTop=area.scrollHeight}
     }
    }
   }
   staffUnreadCount=countUnreadThreads(threads);
   staffChatUnread=staffUnreadCount>0;
   updateNotificationTitle();
   if(JSON.stringify(adminThreads)!==JSON.stringify(threads)){
     adminThreads=threads;
     if(adminTab==='chat'&&!document.activeElement?.matches('#admin-chat-input')){render();scrollChat('admin-chat-messages')}
     else updateAdminNotificationBadge();
   }
  }
 }catch(e){console.warn('Chat poll',e)}finally{chatPollBusy=false}
}
function updateAdminNotificationBadge(){const nav=document.querySelector('.adminnav');if(!nav)return;const btn=[...nav.querySelectorAll('button')].find(x=>x.textContent.includes('Guest Messages'));if(btn)btn.innerHTML='✉ Guest Messages'+(staffUnreadCount?' <span class="unread-badge">'+staffUnreadCount+'</span>':'')}

async function refreshGuest(){const [mine,activities,rooms,resort,settings,menu,orders,amenities]=await Promise.all([loadMine(),api('activities'),api('room-types'),api('resort-info'),api('settings'),api('menu'),api('orders/guest?token='+encodeURIComponent(token)),api('amenities')]);myData=mine;allActivities=activities;roomTypes=rooms;resortInfo=resort;hotelSettings=settings;theme=settings.theme;menuItems=menu;menuOrders=orders;amenityItems=amenities}
async function openGuest(){
  try{
    guest=await api('guest?token='+encodeURIComponent(token));
    await refreshGuest();
    guestChat=(await api('chat/guest?token='+encodeURIComponent(token))).messages;chatGuestLatest=Math.max(0,...guestChat.filter(x=>x.sender==='reception').map(x=>x.id));
    chatGuestReadId=getReadId('guest');
    chatUnreadCount=guestChat.filter(x=>x.sender==='reception'&&x.id>chatGuestReadId).length;
    chatUnread=chatUnreadCount>0;
    if(page==='chat'){chatGuestReadId=chatGuestLatest;storeReadId('guest',chatGuestReadId);chatUnreadCount=0}
    try{const initial=history.state?.stayosGuestPage;if(initial&&guestPages.has(initial))page=initial;history.replaceState({stayosGuestPage:page},'',location.href)}catch(_){}
    updateNotificationTitle();render();
  }catch(e){
    // Revoke an outdated local pass without affecting the original URL or a valid new QR.
    if(!queryToken && /expired|revoked|not yet active|does not exist/i.test(e.message)){
      try{localStorage.removeItem('stayos-guest-pass')}catch(_){}
    }
    app.innerHTML=`<div class="shell"><div class="card pad"><h2>Guest access unavailable</h2><p>${esc(e.message)}</p><p>Your QR pass stays valid until the time set by reception. If the error persists, ask reception to check your access period.</p><button class="btn" onclick="location.reload()">Try again</button></div></div>`;
  }
}
function renderGuest(){document.body.classList.add("guest-mode");document.body.classList.remove("admin-mode");color();let accessible=guest.zones;if((page==='service'||page==='menu')&&!accessible.includes('room'))page='home';if(page==='activities'&&!accessible.includes('activities'))page='home';let content={home:home,service:services,menu:menuView,activities:activityCards,mine,stay:stayView,chat:chatView,explore:exploreView}[page]||home;app.innerHTML=`<div class="phone">${page==='home'?'':`<div class="guest-subheader"><button onclick="navigateGuest('home')" aria-label="${t('home')}">←</button><strong>✧ ${esc(hotelSettings.hotel_name)}</strong><span>${t('room')} ${esc(guest.room)}</span></div>`}${notice()}${page!=='chat'&&page!=='home'?guestChatAlert():''}${content()}<div class="nav">${[['home','⌂',t('home')],['service','🛎',t('service')],['menu','🍽',tt('menu')],['activities','☀',t('activities')],['mine','☑',t('mine')],['chat','✉',t('chat')]].filter(([id])=>id==='home'||id==='mine'||id==='chat'||(id==='service'&&accessible.includes('room'))||(id==='menu'&&accessible.includes('room'))||(id==='activities'&&accessible.includes('activities'))).map(([id,ico,label])=>`<button class="${page===id?'active':''}" onclick="navigateGuest('${id}')"><div style="font-size:19px">${ico}</div>${label}${id==='chat'&&chatUnreadCount?` <span class="unread-badge">${chatUnreadCount}</span>`:''}</button>`).join('')}</div></div>`}
let stays=[],hotelRooms=[],adminMenuItems=[],adminAmenities=[],teamRequests=[],adminBookings=[],foodOrders=[],folioCharges=[];function updateAdmin(){return Promise.all([api('settings'),api('stays'),api('requests'),api('activities'),api('room-types'),api('admin-bookings'),api('chat/threads'),api('orders/admin'),api('folio/admin'),api('hotel-rooms'),api('menu/admin'),api('amenities/admin')]).then(([settings,s,r,a,rt,b,threads,orders,charges,physical,fullMenu,fullAmenities])=>{hotelSettings=settings;theme=settings.theme;stays=s;teamRequests=r;allActivities=a;roomTypes=rt;adminBookings=b;adminThreads=threads;foodOrders=orders;folioCharges=charges;hotelRooms=physical;adminMenuItems=fullMenu;adminAmenities=fullAmenities;staffChatReadId=getReadId('staff');chatStaffLatest=Math.max(0,...threads.map(x=>x.latest_guest_id||0));chatInitialized=true;staffUnreadCount=countUnreadThreads(threads);staffChatUnread=staffUnreadCount>0})}
function adminHeader(){return `<div class="top"><div class="brand">✦ STAYOS<small>HOTEL CONSOLE · DEMO</small></div><div class="row"><button class="btn tiny secondary" onclick="enableAlerts()">${alertsEnabled?'🔔 Sounds on':'🔕 Enable alerts'}</button><span class="tag">🏨 ${esc(hotelSettings.hotel_name)} · English</span><button class="btn tiny secondary" onclick="staffLogout()">Sign out</button></div></div><div class="adminnav">${[['reception','🪪 Reception & QR'],['requests','🛎 Guest Requests'],['food','🍽 Food Orders'],['folio','💳 Room Folio'],['chat','✉ Guest Messages'+(staffUnreadCount?' ('+staffUnreadCount+')':'')],['activities','🌴 Activities'],['rooms','🛏 Rooms & Types'],['catalog','🍹 Menu Catalog'],['amenities','🧺 Guest Amenities'],['branding','🎨 Hotel Branding']].map(([id,label])=>`<button class="${adminTab===id?'active':''}" onclick="adminTab='${id}';render()">${label}</button>`).join('')}</div>`}
function reception(){let now=new Date(),start=dt(now),end=dt(now,3*24*60);return `<div class="reception-layout"><section class="card pad new-access"><div class="section-kicker">FRONT DESK · CHECK-IN</div><h2>New Guest Access</h2><p class="sub">Create a secure QR with room access and precise check-out time.</p><div class="form-row"><div><label>Room number</label><select id="room" onchange="syncReceptionRoom()">${hotelRooms.map(r=>`<option value="${esc(r.room)}">Room ${esc(r.room)} · ${esc(r.room_type_name)}</option>`).join('')}</select></div><div><label>Room category</label><select id="room-type" disabled>${roomTypes.map(rt=>`<option value="${rt.id}">${esc(rt.name)} · max ${rt.max_guests}</option>`).join('')}</select></div></div><label>Number of guests</label><input id="guests" type="number" min="1" max="12" value="2"><div class="form-row"><div><label>Access starts (hotel local time)</label><input id="start" type="datetime-local" value="${start}"></div><div><label>Access expires (hotel local time)</label><input id="ends" type="datetime-local" value="${end}"></div></div><label>Guest permissions</label><div class="permission-grid">${[['room','Room services & dining'],['activities','Activities & experiences'],['pool','Pool & Spa (coming soon)'],['vip','VIP Zone (coming soon)'],['kids','Kids Club (coming soon)']].map(([id,title])=>`<label class="permission-check"><input type="checkbox" class="zone" value="${id}" ${(id==='room'||id==='activities')?'checked':''}> ${title}</label>`).join('')}</div><button class="btn primary-wide" onclick="createStay()">Generate Secure Guest QR →</button><p class="sub small-note">Need another room? <button class="text-link" onclick="adminTab='rooms';render()">Manage hotel rooms ↗</button></p></section><section class="card pad access-list"><div class="row wrap"><div><div class="section-kicker">STAY MANAGEMENT</div><h2>Guest Access Passes</h2></div><span class="pill">${stays.length} passes</span></div><input aria-label="Search room" placeholder="Search by room number..." value="${esc(roomSearch)}" oninput="roomSearch=this.value;filterPasses()"><div id="passes-list">${stays.length?stays.map(x=>`<div class="access-row product" data-pass-room="${esc(x.room)}"><div class="detail"><strong>Room ${esc(x.room)}</strong><div class="sub">${x.guests} guests · ${localeDate(x.ends)}</div><span class="pill ${x.active?'green':''}">${x.revoked?'Revoked':x.active?'Active':'Inactive / Expired'}</span></div><div class="access-actions"><button class="btn tiny secondary" onclick="showQr('${x.id}')">View QR</button>${!x.revoked?`<button class="btn tiny danger" onclick="revokeStay(${x.id})">Revoke</button>`:''}</div></div>`).join(''):'<div class="empty-state">No guest passes yet.<br>Create your first check-in.</div>'}</div></section><div id="qr-area" class="qr-wide"></div></div>`}
function syncReceptionRoom(){const r=hotelRooms.find(x=>x.room===$('#room')?.value);if(r){$('#room-type').value=String(r.room_type_id);const max=roomTypes.find(x=>x.id===r.room_type_id)?.max_guests||2;$('#guests').max=max;$('#guests').value=Math.min(Number($('#guests').value)||2,max)}}
function filterPasses(){document.querySelectorAll('[data-pass-room]').forEach(el=>{el.style.display=el.dataset.passRoom.toLowerCase().includes(roomSearch.toLowerCase().trim())?'':'none'})}
function createStay(){action(async()=>{let room=$('#room').value.trim(),guests=Number($('#guests').value),s=$('#start').value,e=$('#ends').value,zones=[...document.querySelectorAll('.zone:checked')].map(x=>x.value);if(!s||!e||new Date(e)<=new Date(s))throw new Error('End time must be later than start');let data=await api('stays',{room,guests,start:localOffset(s),ends:localOffset(e),zones,room_type_id:Number(hotelRooms.find(x=>x.room===room)?.room_type_id||$('#room-type').value)});await updateAdmin();render();showQr(data.id,data.token)})}
async function showQr(id,provided){
  let s=stays.find(x=>String(x.id)===String(id));if(!s)return;
  let tk=provided||s.token,area=$('#qr-area');if(!area)return;
  let config;
  try {config=await api('network')} catch(e){area.innerHTML='<div class="card pad alert">Network configuration unavailable: '+esc(e.message)+'</div>';return}
  if(!config.guest_base_url){area.innerHTML='<div class="card pad alert">Cannot create a phone QR: no network IP detected. Configure STAYOS_GUEST_BASE_URL and restart the server.</div>';return}
  const url=config.guest_base_url+'/guest?guest='+encodeURIComponent(tk);
  const isLocal=/^http:\/\/(127\.|localhost)/.test(url);
  area.innerHTML=`<div class="card pad" style="margin-top:20px"><h2>Guest QR · Room ${esc(s.room)}</h2><div class="poster"><strong>✦ ${esc(hotelSettings.hotel_name)}</strong><span class="sub">WELCOME TO YOUR STAY</span><img src="/api/qr?token=${encodeURIComponent(tk)}" alt="Scannable guest QR code"><strong>ROOM ${esc(s.room)}</strong><span class="sub">Scan to access guest services</span></div><p class="sub">Valid from ${localeDate(s.start)} until ${localeDate(s.ends)}. Guests: ${s.guests}. Permissions: ${esc(s.zones.join(', '))}.</p><p class="sub"><strong>Phone URL:</strong> <code style="overflow-wrap:anywhere">${esc(url)}</code></p><p class="sub" style="color:#9c5918">Connect your phone and computer to the same Wi-Fi. If the phone cannot open the link, verify the PC's LAN IP, firewall and VPN. ${isLocal?'WARNING: localhost is not reachable from the phone.':''}</p><div class="row wrap"><a class="btn" style="text-decoration:none" download="stayos-room-${esc(s.room)}.png" href="/api/qr?token=${encodeURIComponent(tk)}">Download QR PNG</a><button class="btn secondary" onclick='navigator.clipboard.writeText(${JSON.stringify(url)}).then(()=>alert("Copied"))'>Copy guest link</button><a class="btn secondary" style="text-decoration:none" href="${esc(url)}" target="_blank" rel="noopener">Open guest view</a></div></div>`;
  area.scrollIntoView({behavior:'smooth',block:'center'});
}
function revokeStay(id){if(!confirm('Revoke this QR access immediately?'))return;action(async()=>{await api('revoke',{id});await updateAdmin();render()})}
function requestsAdmin(){let pending=teamRequests.filter(r=>r.status!=='done').length;return `<div class="card pad"><div class="row wrap"><div><h2>Live Guest Requests</h2><p class="sub">Auto-refresh every 4 seconds · ${pending} open requests</p></div><div class="row wrap"><button class="btn tiny ${alertsEnabled?'secondary':''}" onclick="enableAlerts()">${alertsEnabled?'🔔 Sound enabled':'🔕 Enable sound alerts'}</button><button class="btn secondary tiny" onclick="reloadAdmin()">Refresh</button></div></div><div class="two" style="margin:12px 0"><input id="request-search" placeholder="Search room number" value="${esc(requestSearch)}" oninput="requestSearch=this.value;filterRequests()"><select id="request-filter" onchange="requestFilter=this.value;filterRequests()"><option value="all" ${requestFilter==='all'?'selected':''}>All statuses</option><option value="new" ${requestFilter==='new'?'selected':''}>New</option><option value="progress" ${requestFilter==='progress'?'selected':''}>In progress</option><option value="done" ${requestFilter==='done'?'selected':''}>Completed</option></select></div><div style="overflow:auto"><table class="admin-table"><thead><tr><th>Room</th><th>Request</th><th>Qty</th><th>Received</th><th>Status</th><th>Action</th></tr></thead><tbody>${teamRequests.map(r=>`<tr data-request-room="${esc(r.room)}" data-request-status="${esc(r.status)}"><td><strong>${esc(r.room)}</strong></td><td>${esc(r.item==='cleaning'?'Room Cleaning':(dict.en[r.item]||r.item))}</td><td>${r.qty}</td><td>${localeDate(r.created)}</td><td><span class="status ${r.status}">${esc(r.status)}</span></td><td>${r.status==='done'?'✓':`<button class="btn tiny" onclick="updateStatus(${r.id},'${r.status==='new'?'progress':'done'}')">${r.status==='new'?'Start':'Complete'}</button>`}</td></tr>`).join('')||'<tr><td colspan="6">No requests yet.</td></tr>'}</tbody></table></div></div>`}
function filterRequests(){document.querySelectorAll('[data-request-room]').forEach(el=>{el.style.display=el.dataset.requestRoom.toLowerCase().includes(requestSearch.toLowerCase().trim())&&(requestFilter==='all'||el.dataset.requestStatus===requestFilter)?'':'none'})}
function enableAlerts(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error('Audio is not supported');alertContext=alertContext||new AC();alertContext.resume();alertsEnabled=true;playAlert();render()}catch(e){setMessage(e.message)}}
function playAlert(){if(!alertsEnabled||!alertContext)return;try{const now=alertContext.currentTime;[0,.18].forEach((offset,i)=>{const osc=alertContext.createOscillator(),gain=alertContext.createGain();osc.type='sine';osc.frequency.value=i?880:660;gain.gain.setValueAtTime(0.0001,now+offset);gain.gain.exponentialRampToValueAtTime(.12,now+offset+.015);gain.gain.exponentialRampToValueAtTime(.0001,now+offset+.16);osc.connect(gain);gain.connect(alertContext.destination);osc.start(now+offset);osc.stop(now+offset+.17)})}catch(e){console.warn('Sound unavailable',e)}}
let watching=false;let lastBookingId=null,lastFoodId=null;
async function pollAdmin(){if(token||!adminSigned||document.hidden||watching)return;watching=true;try{const [r,s,a,b,orders,charges]=await Promise.all([api('requests'),api('stays'),api('activities'),api('admin-bookings'),api('orders/admin'),api('folio/admin')]);const newest=Math.max(0,...r.map(x=>x.id));const newestBooking=Math.max(0,...b.map(x=>x.id));const latestFood=Math.max(0,...orders.map(x=>x.id));const newFood=lastFoodId!==null&&latestFood>lastFoodId;lastFoodId=latestFood;const newBooking=lastBookingId!==null&&newestBooking>lastBookingId;const isNew=lastRequestId!==null&&newest>lastRequestId;lastBookingId=Math.max(lastBookingId||0,newestBooking);if(isNew||newBooking||newFood){playAlert();if(adminTab!=='requests'&&adminTab!=='activities'){message=newFood?'🔔 New food order!':isNew?'🔔 New guest request received!':'🔔 New activity registration!'} }lastRequestId=Math.max(lastRequestId||0,newest);teamRequests=r;stays=s;allActivities=a;adminBookings=b;foodOrders=orders;folioCharges=charges;if(adminTab==='requests'||adminTab==='activities'||adminTab==='food'||adminTab==='folio'||isNew||newBooking||newFood){const focus=document.activeElement?.id;const pos=document.activeElement?.selectionStart;render();if(focus==='request-search'){const input=$('#request-search');input?.focus();if(Number.isInteger(pos))input?.setSelectionRange(pos,pos)}filterRequests()}}catch(e){console.warn('Live update failed',e)}finally{watching=false}}
const orderStatusLabel={new:'New',preparing:'Preparing',on_way:'On the way',delivered:'Delivered',cancelled:'Cancelled'};
function foodAdmin(){return `<div class="card pad"><div class="row"><h2>Food & Drink Orders</h2><span class="pill">${foodOrders.filter(x=>!['delivered','cancelled'].includes(x.status)).length} active</span></div><p class="sub">Orders show their actual delivery destination and are automatically added to the guest room folio.</p><div class="order-admin-grid">${foodOrders.map(o=>`<article class="card pad"><div class="row"><h3>Order #${o.id} · Room ${esc(o.room)}</h3><span class="pill green">${money(o.total_cents)}</span></div><p><strong>Deliver to:</strong> ${esc(o.delivery_area)} · ${esc(o.delivery_detail)}</p>${o.note?`<p><strong>Notes:</strong> ${esc(o.note)}</p>`:''}<div class="sub">${o.lines.map(z=>esc(orderedProductName(z.product_name))+' × '+z.qty).join(' · ')}</div><div class="row" style="margin-top:12px"><strong>${orderStatusLabel[o.status]||o.status}</strong><select style="max-width:180px" onchange="changeFoodStatus(${o.id},this.value)">${Object.entries(orderStatusLabel).map(([key,label])=>`<option ${o.status===key?'selected':''} value="${key}">${label}</option>`).join('')}</select></div></article>`).join('')||'<p class="sub">No orders yet</p>'}</div></div>`}
async function changeFoodStatus(id,status){try{await api('orders/status',{id,status});await updateAdmin();render()}catch(e){setMessage(e.message)}}
function folioAdmin(){const groups=[...new Map(stays.map(s=>[s.id,s])).values()].filter(s=>folioCharges.some(f=>f.stay_id===s.id));return `<div class="card pad"><h2>Room Folio · Checkout Charges</h2><p class="sub">All totals are in demo THB. Settle only after payment has been received outside STAYOS.</p><div class="folio-search"><input id="folio-search" placeholder="Search room number" oninput="document.querySelectorAll('[data-folio-room]').forEach(x=>x.style.display=x.dataset.folioRoom.includes(this.value.trim())?'':'none')"></div>${groups.map(s=>{let charges=folioCharges.filter(f=>f.stay_id===s.id),open=charges.filter(f=>f.status==='open').reduce((n,f)=>n+f.amount_cents,0);return `<section class="card pad" style="margin:14px 0" data-folio-room="${esc(s.room)}"><div class="row"><h3>Room ${esc(s.room)} · Stay #${s.id}</h3><strong>${money(open)} outstanding</strong></div><table class="admin-table"><thead><tr><th>Description</th><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>${charges.map(f=>`<tr><td>${esc(f.description)}</td><td>${localeDate(f.created)}</td><td>${money(f.amount_cents)}</td><td>${esc(f.status)}</td></tr>`).join('')}</tbody></table>${open>0?`<div class="row wrap" style="margin-top:14px"><select id="pay-method-${s.id}" style="max-width:210px"><option value="card_terminal">Card terminal</option><option value="cash">Cash</option><option value="other">Other / verified</option></select><button class="btn" onclick="settleFolio(${s.id},'${esc(s.room)}',${open})">Mark ${money(open)} as paid</button></div>`:'<span class="pill green">No outstanding charges</span>'}</section>`}).join('')||'<p class="sub">No room charges recorded yet.</p>'}</div>`}
async function settleFolio(stay,room,amount){if(!confirm('Confirm that '+money(amount)+' was ACTUALLY received for room '+room+'? This does not charge a card.'))return;try{await api('folio/settle',{stay_id:stay,method:$('#pay-method-'+stay).value});await updateAdmin();render()}catch(e){setMessage(e.message)}}
const photoOptions={amenities:['towels.svg','water.svg','toothbrush.svg','slippers.svg','soap.svg','paper.svg','cleaning.svg'],room_types:['room-garden.webp','room-ocean.webp','room-villa.webp','resort-pool.webp'],menu_products:['coconut.webp','smoothie.webp','fruit.webp','sandwich.webp','curry.webp','fries.webp','brownie.webp','tea.webp','dining.webp'],activities:['yoga.webp','yoga','cooking','surf','music','tea','craft','resort-pool.webp','wellness-spa.webp']};
function catalogOptions(items,current){return items.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function roomsAdmin(){return `<div class="catalog-view"><div class="section-title row wrap"><div><div class="section-kicker">ROOM INVENTORY</div><h2>Rooms & Room Types</h2><p class="sub">Manage actual room numbers separately from room categories.</p></div><button class="btn" onclick="openCatalog('hotel_rooms')">+ Add Room</button></div><div class="card pad"><h3>Physical Rooms <span class="pill">${hotelRooms.length}</span></h3><div class="inventory-grid">${hotelRooms.map(r=>`<div class="inventory-card"><div><strong>Room ${esc(r.room)}</strong><p class="sub">${esc(r.room_type_name)} · Floor ${esc(r.floor||'—')}</p></div><button class="btn tiny secondary" onclick="openCatalog('hotel_rooms',${r.id})">Edit</button><button class="btn tiny danger" onclick="deleteCatalog('hotel_rooms',${r.id})">Delete</button></div>`).join('')}</div></div><div class="section-title row wrap"><h3>Room Categories</h3><button class="btn secondary" onclick="openCatalog('room_types')">+ Add Room Type</button></div><div class="catalog-card-grid">${roomTypes.map(rt=>`<article class="card"><img class="catalog-photo" src="${roomImage(rt.image)}" alt="${esc(rt.name)}"><div class="pad"><h3>${esc(rt.name)}</h3><p class="sub">${esc(rt.description)}</p><p class="sub">${esc(rt.size)} · up to ${rt.max_guests} guests</p><div class="row wrap"><button class="btn tiny secondary" onclick="openCatalog('room_types',${rt.id})">Edit</button><button class="btn tiny danger" onclick="deleteCatalog('room_types',${rt.id})">Delete</button></div></div></article>`).join('')}</div></div>`}
function amenitiesAdmin(){return `<div class="catalog-view"><div class="section-title row wrap"><div><div class="section-kicker">ROOM SERVICE</div><h2>Guest Amenities</h2><p class="sub">Create housekeeping supplies with guest or room limits and daily or per-stay allowances.</p></div><button class="btn" onclick="openCatalog('amenities')">+ Add Amenity</button></div><div class="catalog-card-grid">${adminAmenities.map(a=>`<article class="card"><img class="catalog-photo" src="/assets/${esc(a.image)}" alt="${esc(a.name)}"><div class="pad"><h3>${esc(a.name)}</h3><p class="sub">${esc(a.name_he)}</p><p class="sub">${a.basis==='guest'?'Per guest':'Per room'} · ${a.period==='daily'?'Daily':'Entire stay'} · ${a.enabled?'Available':'Hidden'}</p><div class="row wrap"><button class="btn tiny secondary" onclick="openCatalog('amenities','${esc(a.id)}')">Edit</button><button class="btn tiny danger" onclick="deleteCatalog('amenities','${esc(a.id)}')">Remove</button></div></div></article>`).join('')}</div></div>`}
function menuCatalogAdmin(){return `<div class="catalog-view"><div class="section-title row wrap"><div><div class="section-kicker">DINING MANAGEMENT</div><h2>Menu & Products</h2><p class="sub">Add products, set prices in USD, translate names and choose photos.</p></div><button class="btn" onclick="openCatalog('menu_products')">+ Add Product</button></div><div class="catalog-card-grid">${adminMenuItems.map(p=>`<article class="card"><img class="catalog-photo" src="/assets/${esc(p.image)}" alt="${esc(p.name)}"><div class="pad"><span class="pill">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p class="sub">${esc(p.name_he)}</p><strong>$${(p.price_cents/100).toFixed(2)}</strong><p class="sub">${p.available?'Available':'Hidden from guests'}</p><div class="row wrap"><button class="btn tiny secondary" onclick="openCatalog('menu_products',${p.id})">Edit</button><button class="btn tiny danger" onclick="deleteCatalog('menu_products',${p.id})">${p.available?'Remove':'Delete'}</button></div></div></article>`).join('')}</div></div>`}
function updateStatus(id,status){action(async()=>{await api('status',{id,status});await updateAdmin();render()})}
function activitiesAdmin(){return `<div class="catalog-view"><div class="section-title row wrap"><div><div class="section-kicker">RESORT EXPERIENCES</div><h2>Activity Schedule</h2><p class="sub">Schedule experiences, edit capacity and create new activities.</p></div><button class="btn" onclick="openCatalog('activities')">+ Add Activity</button></div><div class="catalog-card-grid">${allActivities.map(a=>`<article class="card"><img class="catalog-photo" src="${imageFor(a.image)}" alt="${esc(a.title)}"><div class="pad"><h3>${esc(a.title)}</h3><p class="sub">${localeDate(a.starts)} · ${esc(a.location)}</p><p class="sub">${a.booked}/${a.capacity} registered · $${Number(a.price).toFixed(2)}</p><div class="row wrap"><button class="btn tiny secondary" onclick="openCatalog('activities',${a.id})">Edit</button><button class="btn tiny danger" onclick="deleteCatalog('activities',${a.id})">Delete</button></div></div></article>`).join('')}</div><div class="card pad"><h3>Guest Registrations (${adminBookings.length})</h3><div class="table-scroll"><table class="admin-table"><thead><tr><th>Room</th><th>Activity</th><th>Participants</th><th>Starts</th></tr></thead><tbody>${adminBookings.map(b=>`<tr><td>${esc(b.room)}</td><td>${esc(b.title)}</td><td>${b.qty}</td><td>${localeDate(b.starts)}</td></tr>`).join('')||'<tr><td colspan="4">No registrations</td></tr>'}</tbody></table></div></div></div>`}
function catalogField(label,name,value,type='text',extra=''){return `<label class="catalog-field">${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`}
function catalogSelect(label,name,items,value){return `<label class="catalog-field">${label}<select name="${name}">${items.map(it=>{const v=typeof it==='string'?it:it.value;const t=typeof it==='string'?it:it.label;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}

function openCatalog(section,id=0){const source={hotel_rooms:hotelRooms,room_types:roomTypes,menu_products:adminMenuItems,activities:allActivities,amenities:adminAmenities}[section]||[];const obj=source.find(x=>String(x.id)===String(id))||{};const title={hotel_rooms:'Hotel Room',room_types:'Room Type',menu_products:'Menu Product',activities:'Activity',amenities:'Amenity'}[section];let fields='';if(section==='amenities')fields=(id?'':catalogField('Unique code (a-z, 0-9, _ and -)','slug','','text','required pattern="[a-z][a-z0-9_-]+"'))+catalogField('Name (English)','name',obj.name,'text','required')+catalogField('Name (Hebrew)','name_he',obj.name_he,'text','required')+catalogSelect('Quantity basis','basis',[{value:'guest',label:'One per guest'},{value:'room',label:'Per room (max 2)'}],obj.basis||'guest')+catalogSelect('Limit period','period',[{value:'daily',label:'Each day'},{value:'stay',label:'Entire stay'}],obj.period||'daily')+catalogSelect('Image','image',photoOptions.amenities,obj.image||'towels.svg')+catalogSelect('Status','enabled',[{value:'1',label:'Available'},{value:'0',label:'Hidden'}],String(obj.enabled??1));
if(section==='hotel_rooms')fields=catalogField('Room number','room',obj.room,'text','required maxlength="16"')+catalogSelect('Room category','room_type_id',roomTypes.map(t=>({value:String(t.id),label:t.name})),String(obj.room_type_id||roomTypes[0]?.id||''))+catalogField('Floor','floor',obj.floor||'')+catalogField('Notes','notes',obj.notes||'');
if(section==='room_types')fields=catalogField('Room type name (English)','name',obj.name,'text','required')+catalogField('Description','description',obj.description,'text','required')+catalogField('Size','size',obj.size||'42 m²','text','required')+catalogField('Maximum guests','max_guests',obj.max_guests||3,'number','min="1" max="20" required')+catalogSelect('Photo','image',photoOptions.room_types,obj.image||photoOptions.room_types[0]);
if(section==='menu_products')fields=catalogField('Name (English)','name',obj.name,'text','required')+catalogField('Name (Hebrew)','name_he',obj.name_he,'text','required')+catalogField('Description (English)','description',obj.description,'text','required')+catalogField('Description (Hebrew)','description_he',obj.description_he,'text','required')+catalogSelect('Category','category',['drinks','food','snacks'],obj.category||'drinks')+catalogField('Price (USD)','price_thb',obj.id?(obj.price_cents/100).toFixed(2):'','number','min="0" step="0.01" required')+catalogSelect('Photo','image',photoOptions.menu_products,obj.image||photoOptions.menu_products[0])+`<label class="catalog-field">Available to guests <select name="available"><option value="1" ${obj.available!==0?'selected':''}>Yes</option><option value="0" ${obj.available===0?'selected':''}>No</option></select></label>`;
if(section==='activities'){const d=x=>x?new Date(x).toISOString().slice(0,16):'';fields=catalogField('Activity name','title',obj.title,'text','required')+catalogField('Description','description',obj.description,'text','required')+catalogField('Location','location',obj.location||'Pool Deck','text','required')+catalogField('Starts','starts_local',d(obj.starts),'datetime-local','required')+catalogField('Ends','ends_local',d(obj.ends),'datetime-local','required')+catalogField('Capacity','capacity',obj.capacity||12,'number','min="1" required')+catalogField('Price (USD)','price',obj.price??0,'number','min="0" step="0.01" required')+catalogSelect('Photo','image',photoOptions.activities,obj.image||'yoga.webp')}
if(['room_types','menu_products','activities','amenities'].includes(section))fields+=`<label class="catalog-field upload-field">Upload a new photo (JPG / PNG / WebP, max 4 MB)<input type="file" name="custom_photo" accept="image/jpeg,image/png,image/webp"><small>Uploaded photos become part of the hotel demo asset library.</small></label>`;
const wrap=document.createElement('div');wrap.className='catalog-overlay';wrap.innerHTML=`<section class="catalog-dialog" role="dialog" aria-modal="true"><div class="row"><div><div class="section-kicker">HOTEL CATALOG</div><h2>${id?'Edit':'Add'} ${title}</h2></div><button type="button" class="btn secondary" id="cancel-catalog">×</button></div><form id="catalog-form" class="catalog-form">${fields}<div class="catalog-dialog-actions"><button class="btn" type="submit">Save ${title}</button><button class="btn secondary" type="button" id="cancel-catalog-bottom">Cancel</button></div></form></section>`;document.body.appendChild(wrap);wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};wrap.querySelector('#cancel-catalog').onclick=wrap.querySelector('#cancel-catalog-bottom').onclick=()=>wrap.remove();wrap.querySelector('form').onsubmit=async e=>{e.preventDefault();const btn=wrap.querySelector('button[type="submit"]');btn.disabled=true;try{const record=Object.fromEntries(new FormData(e.target));if(id)record.id=id;if(section==='amenities')record.enabled=Number(record.enabled);delete record.custom_photo;const photo=e.target.querySelector('[name="custom_photo"]')?.files?.[0];if(photo){if(photo.size>4*1024*1024)throw new Error('Photo exceeds 4MB');const upload=await fetch('/api/upload-asset',{method:'POST',headers:{'Content-Type':photo.type},body:photo});const uploaded=await upload.json();if(!upload.ok)throw new Error(uploaded.error||'Photo upload failed');record.image=uploaded.image}if(section==='menu_products'){record.price_cents=Math.round(Number(record.price_thb)*100);delete record.price_thb;record.available=Number(record.available)}if(section==='activities'){record.starts=localOffset(record.starts_local);record.ends=localOffset(record.ends_local);delete record.starts_local;delete record.ends_local}await api('catalog',{section,record,action:'save'});wrap.remove();await updateAdmin();render();setMessage('Saved successfully')}catch(err){btn.disabled=false;alert(err.message)}}}
async function deleteCatalog(section,id){if(!confirm('Delete this item? Items with historical bookings or orders are protected.'))return;try{await api('catalog',{section,action:'delete',record:{id}});await updateAdmin();render()}catch(e){alert(e.message)}}
function brandingAdmin(){return `<div class="card pad"><h2>Hotel Brand & Guest App</h2><p class="sub">White label: updates are saved for this demo hotel and appear in guest devices after refresh.</p><label>Hotel display name</label><input id="brand-name" maxlength="80" value="${esc(hotelSettings.hotel_name)}"><label>Welcome message (English)</label><input id="brand-welcome" maxlength="120" value="${esc(hotelSettings.welcome)}"><label>Color palette</label><div class="grid">${Object.keys(themePresets).map(id=>`<button class="tile" onclick="selectBrandTheme('${id}')"><div style="height:38px;background:${themePresets[id].primary};border-bottom:9px solid ${themePresets[id].accent};border-radius:9px;margin-bottom:12px"></div><strong>${id==='luxury'?'Tropical Luxury':id==='ocean'?'Ocean Escape':'Modern Boutique'}</strong> ${theme===id?'✓':''}</button>`).join('')}</div><button class="btn" style="margin-top:20px" onclick="saveBranding()">Save Hotel Branding</button><h3>Guest languages</h3><p>English · Hebrew · Russian · French. Admin remains English only.</p><p class="sub">The photo collection illustrates our fictional AZURA demo resort. For a real hotel, replace example imagery with photography approved by that hotel.</p></div>`}
function selectBrandTheme(id){const n=$('#brand-name')?.value,w=$('#brand-welcome')?.value;theme=id;render();if(n!==undefined)$('#brand-name').value=n;if(w!==undefined)$('#brand-welcome').value=w}
async function saveBranding(){try{const name=$('#brand-name')?.value.trim(),welcome=$('#brand-welcome')?.value.trim();hotelSettings=await api('settings',{hotel_name:name,welcome,theme});message='Hotel branding saved for guest app';render()}catch(e){setMessage(e.message)}}
function renderLogin(){document.body.classList.remove('guest-mode');document.body.classList.add('admin-mode');app.innerHTML=`<div class="staff-login-screen"><div class="staff-login-photo"></div><div class="staff-login-panel"><div class="brand">✧ STAYOS<small>HOTEL CONSOLE</small></div><div class="section-kicker" style="margin-top:45px">STAFF ACCESS</div><h1>Welcome back.</h1><p class="sub">Sign in to the hotel console to manage guest passes, requests, activities and messages.</p><form onsubmit="staffLogin(event)"><label>Staff password</label><input id="staff-password" type="password" autocomplete="current-password" required placeholder="Enter hotel password"><button class="btn" style="width:100%;margin-top:20px" type="submit">Sign in securely →</button></form>${notice()}<p class="sub" style="font-size:12px;margin-top:24px">Local demo password is documented in README. Change it before any public deployment.</p></div></div>`}
async function staffLogin(e){e.preventDefault();const input=$('#staff-password');try{await api('auth/login',{password:input.value});adminSigned=true;message='';await updateAdmin();render()}catch(err){message=err.message;renderLogin()}}
async function staffLogout(){await api('auth/logout',{});adminSigned=false;stays=[];teamRequests=[];adminThreads=[];renderLogin()}
function renderAdmin(){if(!adminSigned){renderLogin();return}document.body.classList.remove("guest-mode");document.body.classList.add("admin-mode");color();document.documentElement.dir='ltr';document.documentElement.lang='en';document.body.classList.remove('rtl');let views={reception,requests:requestsAdmin,food:foodAdmin,folio:folioAdmin,chat:adminChatView,activities:activitiesAdmin,rooms:roomsAdmin,catalog:menuCatalogAdmin,amenities:amenitiesAdmin,branding:brandingAdmin};app.innerHTML=`<div class="shell">${adminHeader()}${notice()}${views[adminTab]()}<p class="sub" style="margin-top:30px">DEMO ONLY · Staff password is basic; HTTPS and hardened authentication required for deployment.</p></div>`}
async function reloadAdmin(){await updateAdmin();render()}
function render(){if(token&&guest)renderGuest();else if(!token)renderAdmin()}
window.addEventListener('pageshow',()=>{if(token&&guest)pollChats()});
window.addEventListener('visibilitychange',()=>{if(!document.hidden)pollChats()});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(token&&guest&&page==='home')render()});
function installBanner(){if(installDismissed||matchMedia('(display-mode: standalone)').matches||navigator.standalone)return '';return `<div class="install-card"><strong>📲 ${tt('installTitle')}</strong><p class="sub">${tt('installDesc')}</p><div class="row"><button class="btn tiny" onclick="installGuest()">${tt('installAction')}</button><button class="btn secondary tiny" onclick="installDismissed=true;render()">${tt('later')}</button></div></div>`}
async function installGuest(){if(installPrompt){try{const p=installPrompt;await p.prompt();const result=await p.userChoice;if(result.outcome==='accepted'){installDismissed=true;render();return}}catch(e){console.warn(e)}}
 const ios=/iPad|iPhone|iPod/.test(navigator.userAgent);const chrome=/Android/.test(navigator.userAgent);
 const manual=ios?tr('באייפון: פתחו בספארי ← לחצו על כפתור השיתוף (ריבוע עם חץ) ← ״הוספה למסך הבית״ ← ״הוסף״.','On iPhone Safari: tap Share → Add to Home Screen → Add.'):chrome?tr('באנדרואיד: בתפריט Chrome (⋮) בחרו ״הוספה למסך הבית״ או ״התקנת אפליקציה״.','In Chrome: open menu (⋮) → Add to Home screen / Install app.'):tr('בתפריט הדפדפן בחרו הוספה למסך הבית.','Use the browser menu to add the page to your Home Screen.');
 const hint=location.protocol!=='https:'&&location.hostname!=='localhost'?tr('האתר כרגע פועל בחיבור HTTP ברשת מקומית. התקנה אמיתית בלחיצה אחת דורשת HTTPS ודפדפן תומך.','Your local HTTP address cannot offer a native one-tap install; HTTPS and a supported browser are required.') :tr('באייפון אין אפשרות להתקין אוטומטית דרך כפתור באתר; זו מגבלה של Safari.','iPhone Safari does not allow websites to trigger one-tap installation.');
 const overlay=document.createElement('div');overlay.className='booking-overlay';overlay.innerHTML=`<div class="booking-modal" role="dialog" aria-modal="true" dir="${language==='he'?'rtl':'ltr'}"><button class="booking-close">×</button><h2>${tt('installManual')}</h2><p>${manual}</p><p class="sub">${hint}</p><button class="btn close-install">${tt('close')}</button></div>`;document.body.appendChild(overlay);overlay.querySelector('.booking-close').onclick=overlay.querySelector('.close-install').onclick=()=>overlay.remove();}

setInterval(pollAdmin,4000);setInterval(pollChats,3000);
(async()=>{if(token)await openGuest();else{try{adminSigned=(await api('auth/me')).authenticated}catch(_){adminSigned=false}if(adminSigned)await updateAdmin();render()}})().catch(e=>{app.innerHTML='<div class="shell alert">'+esc(e.message)+' <button class="btn" onclick="location.reload()">Retry</button></div>'});

if((location.protocol==='https:'||location.hostname==='localhost')&&'serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').catch(e=>console.info('PWA registration unavailable',e))}
